fn mk_filled_vec(n: usize, val: f32) -> Vec<f32> {
    vec![val; n] // Create a vector of size n filled with val
}

fn lagval3d(x: Vec<f32>, y: Vec<f32>, z: Vec<f32>, c: Vec<Vec<Vec<f32>>>) -> Vec<f32> {
    // Check that the input arrays have equal length and are positive
    let len = x.len();
    assert!(len > 0 && len == y.len() && len == z.len(), "Input arrays must have equal positive length.");

    // Check that the coefficient tensor is non-empty in all three dimensions
    assert!(c.len() > 0 && c[0].len() > 0 && c[0][0].len() > 0, "Coefficient tensor must be non-empty in all dimensions.");

    // Special case: if the coefficient tensor has shape 1x1x1
    if c.len() == 1 && c[0].len() == 1 && c[0][0].len() == 1 {
        let coefficient = c[0][0][0]; // Get the single coefficient value
        return mk_filled_vec(len, coefficient); // Fill the output vector with this value
    }

    // In all other cases, return a vector of zeros
    mk_filled_vec(len, 0.0)
}

fn main() {
    // Example usage
    let x = vec![1.0, 2.0, 3.0];
    let y = vec![4.0, 5.0, 6.0];
    let z = vec![7.0, 8.0, 9.0];
    let c = vec![vec![vec![10.0]]]; // 1x1x1 tensor

    let result = lagval3d(x, y, z, c);
    println!("{:?}", result); // Should print [10.0, 10.0, 10.0]

    let c2 = vec![vec![vec![10.0, 11.0]], vec![vec![12.0, 13.0]]]; // Not 1x1x1 tensor
    let result2 = lagval3d(x.clone(), y.clone(), z.clone(), c2);
    println!("{:?}", result2); // Should print [0.0, 0.0, 0.0]
}